import unittest
from candidate import string_xor


class TestStringXor(unittest.TestCase):
    def test_normal_case_binary_xor(self):
        self.assertEqual(string_xor('010', '110'), '100')

    def test_all_zeros_input(self):
        self.assertEqual(string_xor('0000', '0000'), '0000')

    def test_all_ones_input(self):
        self.assertEqual(string_xor('1111', '1111'), '0000')

    def test_alternating_pattern(self):
        self.assertEqual(string_xor('10101', '01010'), '11111')

    def test_single_character_ones_xor_zeros(self):
        self.assertEqual(string_xor('1', '0'), '1')

    def test_single_character_zeros_xor_ones(self):
        self.assertEqual(string_xor('0', '1'), '1')

    def test_empty_strings_input(self):
        self.assertEqual(string_xor('', ''), '')

    def test_unequal_length_inputs_truncates(self):
        self.assertEqual(string_xor('1100', '10'), '01')

    def test_none_first_argument_raises_error(self):
        with self.assertRaises(TypeError):
            string_xor(None, '010')

    def test_none_second_argument_raises_error(self):
        with self.assertRaises(TypeError):
            string_xor('010', None)

    def test_integer_inputs_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_xor(123, 101)

    def test_list_inputs_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_xor([1, 0], [0, 1])


if __name__ == '__main__':
    unittest.main()
